def __table_history__(cls):
    if not cls._history:
        raise ValueError('No history table')
    return Table(cls._table + '__history')

def _update_history_table(cls):
    if cls._history:
        history_table = cls.__table_handler__(history=True)
        for field_name, field in cls._fields.items():
            if not field.sql_type() or isinstance(field, fields.Function):
                continue
            history_table.add_column(field_name, field._sql_type)

def _insert_history(cls, ids, deleted=False):
    transaction = Transaction()
    cursor = transaction.connection.cursor()
    if not cls._history:
        return
    user = transaction.user
    table = cls.__table__()
    history = cls.__table_history__()
    columns = []
    hcolumns = []
    if not deleted:
        fields_ = cls._fields
    else:
        fields_ = {
            'id': cls.id,
            'write_uid': cls.write_uid,
            'write_date': cls.write_date,
            }
    for fname, field in sorted(fields_.items()):
        if not field.sql_type() or isinstance(field, fields.Function):
            continue
        columns.append(Column(table, fname))
        hcolumns.append(Column(history, fname))
    if not deleted:
        where = fields.SQL_OPERATORS['in'](table.id, ids)
        cursor.execute(*history.insert(hcolumns,
                table.select(*columns, where=where)))
    else:
        if transaction.database.has_multirow_insert():
            for sub_ids in grouped_slice(ids, backend.MAX_QUERY_PARAMS):
                cursor.execute(*history.insert(hcolumns,
                        [[id_, CurrentTimestamp(), user]
                            for id_ in sub_ids]))
        else:
            for id_ in ids:
                cursor.execute(*history.insert(hcolumns,
                        [[id_, CurrentTimestamp(), user]]))

def restore_history(cls, ids, datetime):
    'Restore record ids from history at the date time'
    cls._restore_history(ids, datetime)

def restore_history_before(cls, ids, datetime):
    'Restore record ids from history before the date time'
    cls._restore_history(ids, datetime, _before=True)

def create(cls, vlist):
    transaction = Transaction()
    cursor = transaction.connection.cursor(row_factory=backend.scalar_row)
    pool = Pool()
    Translation = pool.get('ir.translation')

    vlist_orig = vlist
    vlist = cls._before_create(vlist)

    table = cls.__table__()
    modified_fields = set()
    defaults_cache = {}  # Store already computed default values
    missing_defaults = {}  # Store missing default values by schema
    new_ids = []

    def db_insert(columns, vlist, column_names):
        if transaction.database.has_multirow_insert():
            vlist = (
                s for s in grouped_slice(
                    vlist,
                    backend.MAX_QUERY_PARAMS // (len(columns) + 1)))
        else:
            vlist = ([v] for v in vlist)

        for values in vlist:
            values = list(values)
            cols = list(columns)
            try:
                if len(values) > 1:
                    ids = transaction.database.nextid(
                        transaction.connection, cls._table,
                        count=len(values))
                    if ids is not None:
                        assert len(ids) == len(values)
                        cols.append(table.id)
                        for val, id in zip(values, ids):
                            val.append(id)
                        cursor.execute(*table.insert(cols, values))
                        yield from ids
                        continue
                for i, val in enumerate(values):
                    if transaction.database.has_returning():
                        cursor.execute(*table.insert(
                                cols, [val], [table.id]))
                        yield from cursor
                    else:
                        id_new = transaction.database.nextid(
                            transaction.connection, cls._table)
                        if id_new:
                            if i == 0:
                                cols.append(table.id)
                            val.append(id_new)
                            cursor.execute(*table.insert(cols, [val]))
                        else:
                            cursor.execute(*table.insert(cols, [val]))
                            id_new = transaction.database.lastid(cursor)
                        yield id_new
            except (
                    backend.DatabaseIntegrityError,
                    backend.DatabaseDataError
                    ) as exception:
                if isinstance(exception, backend.DatabaseIntegrityError):
                    raise_func = cls.__raise_integrity_error
                elif isinstance(exception, backend.DatabaseDataError):
                    raise_func = cls.__raise_data_error
                with transaction.new_transaction():
                    for value in values:
                        skip = len(['create_uid', 'create_date'])
                        recomposed = dict(zip(column_names, value[skip:]))
                        raise_func(
                            exception, recomposed, transaction=transaction)
                    raise

    to_insert = []
    previous_columns = [table.create_uid, table.create_date]
    previous_column_names = []

    for values in vlist:
        # Clean values
        for key in ('create_uid', 'create_date',
                'write_uid', 'write_date', 'id'):
            if key in values:
                del values[key]
        modified_fields |= values.keys()

        # Get default values
        values_schema = tuple(sorted(values))
        if values_schema not in missing_defaults:
            default = []
            missing_defaults[values_schema] = default_values = {}
            for fname, field in cls._fields.items():
                if fname in values:
                    continue
                if fname in [
                        'create_uid', 'create_date',
                        'write_uid', 'write_date', 'id']:
                    continue
                if isinstance(field, fields.Function) and not field.setter:
                    continue
                if fname in defaults_cache:
                    default_values[fname] = defaults_cache[fname]
                else:
                    default.append(fname)

            if default:
                defaults = cls.default_get(default, with_rec_name=False)
                default_values.update(cls._clean_defaults(defaults))
                defaults_cache.update(default_values)
        values.update(missing_defaults[values_schema])

        current_column_names = []
        current_columns = [table.create_uid, table.create_date]
        current_values = [transaction.user, CurrentTimestamp()]

        # Insert record
        for fname, value in sorted(values.items()):
            field = cls._fields[fname]
            if not hasattr(field, 'set'):
                current_columns.append(Column(table, fname))
                current_values.append(field.sql_format(value))
                current_column_names.append(fname)

        if current_column_names != previous_column_names:
            if to_insert:
                new_ids.extend(db_insert(
                        previous_columns, to_insert,
                        previous_column_names))
                to_insert.clear()
            previous_columns = current_columns
            previous_column_names = current_column_names
        to_insert.append(current_values)
    else:
        if to_insert:
            new_ids.extend(db_insert(
                    current_columns, to_insert, current_column_names))

    # Update path before fields_to_set which could create children
    if cls._path_fields:
        field_names = list(sorted(cls._path_fields))
        cls._set_path(field_names, repeat(new_ids, len(field_names)))
    # Update mptt before fields_to_set which could create children
    if cls._mptt_fields:
        field_names = list(sorted(cls._mptt_fields))
        cls._update_mptt(field_names, repeat(new_ids, len(field_names)))

    translation_values = {}
    fields_to_set = {}
    for values, new_id in zip(vlist, new_ids):
        for fname, value in values.items():
            field = cls._fields[fname]
            if (getattr(field, 'translate', False)
                    and not hasattr(field, 'set')):
                translation_values.setdefault(
                    '%s,%s' % (cls.__name__, fname), {})[new_id] = (
                        field.sql_format(value))
            if hasattr(field, 'set'):
                args = fields_to_set.setdefault(fname, [])
                actions = iter(args)
                for ids, val in zip(actions, actions):
                    if val == value:
                        ids.append(new_id)
                        break
                else:
                    args.extend(([new_id], value))

    if translation_values:
        for name, translations in translation_values.items():
            Translation.set_ids(name, 'model', Transaction().language,
                list(translations.keys()), list(translations.values()))

    for fname in sorted(fields_to_set, key=cls.index_set_field):
        fargs = fields_to_set[fname]
        field = cls._fields[fname]
        field.set(cls, fname, *fargs)

    cls._insert_history(new_ids)

    cls.__check_domain_rule(new_ids, 'create')
    return cls.browse(cls._after_create(new_ids, vlist_orig))

def before_insert(self):
	self.full_name = strip_html(get_fullname(self.user))
	self.date = now()

def set_status(self):
	if not self.is_new():
		return

	if self.reference_doctype and self.reference_name:
		self.status = "Linked"

def set_ip_address(self):
	if self.operation in ("Login", "Logout"):
		self.ip_address = frappe.local.request_ip

def clear_old_logs(days=None):
	if not days:
		days = 90
	doctype = DocType("Activity Log")
	frappe.db.delete(doctype, filters=(doctype.creation < (Now() - Interval(days=days))))

def add_authentication_log(subject, user, operation="Login", status="Success"):
	frappe.get_doc(
		{
			"doctype": "Activity Log",
			"user": user,
			"status": status,
			"subject": subject,
			"operation": operation,
		}
	).insert(ignore_permissions=True, ignore_links=True)

def can_cancel_document(doctype: str):
	workflow = get_workflow(doctype)
	cancelling_states = [s.state for s in workflow.states if s.doc_status == "2"]
	if not cancelling_states:
		return True

	for transition in workflow.transitions:
		if transition.next_state in cancelling_states:
			return False
	return True

def print_workflow_log(messages, title, doctype, indicator):
	if messages.keys():
		msg = f"<h4>{title}</h4>"

		for doc in messages.keys():
			if len(messages[doc]):
				html = f"<details><summary>{frappe.utils.get_link_to_form(doctype, doc)}</summary>"
				for log in messages[doc]:
					if log.get("message"):
						html += "<div class='small text-muted' style='padding:2.5px'>{}</div>".format(
							log.get("message")
						)
				html += "</details>"
			else:
				html = f"<div>{doc}</div>"
			msg += html

		frappe.msgprint(
			msg, title=_("Workflow Status"), indicator=indicator, is_minimizable=True, realtime=True
		)

def set_workflow_state_on_action(doc, workflow_name, action):
	workflow = frappe.get_doc("Workflow", workflow_name)
	workflow_state_field = workflow.workflow_state_field

	# If workflow state of doc is already correct, don't set workflow state
	for state in workflow.states:
		if state.state == doc.get(workflow_state_field) and doc.docstatus == cint(state.doc_status):
			return

	action_map = {"update_after_submit": "1", "submit": "1", "cancel": "2"}
	docstatus = action_map[action]
	for state in workflow.states:
		if state.doc_status == docstatus:
			doc.set(workflow_state_field, state.state)
			return

def _compute_linked_message_ids(self):
    """ Compute the linked messages from the body of the message."""
    message_ids_by_message = defaultdict(list)
    for message in self._filtered_access('read'):
        if tools.is_html_empty(message.body):
            continue
        str_ids = html.fromstring(message.body).xpath(
            "//a[contains(@class, 'o_message_redirect') and @data-oe-model='mail.message']/@data-oe-id",
        )
        for str_id in str_ids:
            with contextlib.suppress(ValueError, TypeError):
                message_ids_by_message[message].append(int(str_id))
    mids = [mid for mids in message_ids_by_message.values() for mid in mids]
    if not mids:
        self.linked_message_ids = self.env["mail.message"]
        return
    # Remove any potential sudo from the env as linked messages are user input, returning them
    # as sudo could lead to users being able to read any arbitrary message through this feature.
    # Only allowed messages for the current user are acceptable.
    linked_messages = self.sudo(False).search(Domain("id", "in", mids))
    for message in self:
        message.linked_message_ids = linked_messages.filtered(
            lambda m, message=message: m.id in message_ids_by_message[message],
        )

def _compute_record_name(self):
    free = self.filtered(lambda m: not m.model or not m.res_id or m.model not in self.env)
    free.record_name = False
    # sudo here, as it behaves like a m2o -> can read message, can read name_get
    for message, record in (self - free)._record_by_message().items():
        try:
            message.record_name = record.sudo().display_name
        except MissingError:
            message.record_name = False

def _compute_is_current_user_or_guest_author(self):
    user = self.env.user
    guest = self.env['mail.guest']._get_guest_from_context()
    for message in self:
        if not user._is_public() and (message.author_id and message.author_id == user.partner_id):
            message.is_current_user_or_guest_author = True
        elif message.author_guest_id and message.author_guest_id == guest:
            message.is_current_user_or_guest_author = True
        else:
            message.is_current_user_or_guest_author = False

def _search_needaction(self, operator, operand):
    if operator not in ('in', 'not in'):
        return NotImplemented
    is_read = operator == 'not in'
    notification_ids = self.env['mail.notification']._search([('res_partner_id', '=', self.env.user.partner_id.id), ('is_read', '=', is_read)])
    return [('notification_ids', 'in', notification_ids)]

def _compute_has_error(self):
    error_from_notification = self.env['mail.notification'].sudo().search([
        ('mail_message_id', 'in', self.ids),
        ('notification_status', 'in', ('bounce', 'exception'))]).mapped('mail_message_id')
    for message in self:
        message.has_error = message in error_from_notification

def _search_has_error(self, operator, operand):
    if operator != 'in':
        return NotImplemented
    return [('notification_ids.notification_status', 'in', ('bounce', 'exception'))]

def _compute_is_bookmarked(self):
    """ Compute if the message is bookmarked by the current user. """
    # TDE FIXME: use SQL
    bookmarked = (
        self.sudo()
        .filtered(lambda msg: self.env.user.partner_id in msg.bookmarked_partner_ids)
        .sudo(False)
    )
    for message in self:
        message.is_bookmarked = message in bookmarked

def _search_is_bookmarked(self, operator, operand):
    if operator != 'in':
        return NotImplemented
    return [('bookmarked_partner_ids', 'in', self.env.user.partner_id.ids)]

def _compute_has_poll(self):
    for message in self:
        message.has_poll = message.started_poll_ids or message.ended_poll_ids

def _get_search_domain_share(self):
    if self.env.user._is_internal():
        return Domain.TRUE
    return SHARE_DOMAIN

def _filter_accessible_from_query(self, query: models.Query, operation: str) -> Self:
    """ Return the subset of ``self`` that satisfies the specific conditions
    for messages. Flush current recordset or the model on empty self.

    Access rules of mail.message:
        - read: if any
            - author_id == pid, uid is the author
            - create_uid == uid, uid is the creator
            - pid is in the recipients (partner_ids + partner_cc_ids)
            - pid has been notified (needaction)
            - uid has access on the related document
        - write: if any
            - author_id == pid, uid is the author
            - pid is in the recipients (partner_ids + partner_cc_ids)
            - pid has been notified (needaction)
            - uid has access on the related document
        - create: if any
            - no model, no res_id (private message)
            - is a user notification (private message)
            - pid in message_follower_ids if model, res_id
            - uid has access on the related document
        - unlink: if
            - uid has access on the related document

    Access on related document is custom custom per model. The rule only
    applies for messages that are not user notifications.

    Global restriction: non employee users cannot see internal messages (aka logs):
    'is_internal' flag on message, 'internal' flag on subtype.
    """
    assert query._model._name == self._name
    if query.is_empty():
        return self.browse()

    # Read the value of messages in order to determine their accessibility.
    # The values are put in 'messages_to_check', and entries are popped
    # once we know they are accessible. At the end, the remaining entries
    # are the invalid ones.
    if self:
        self.flush_recordset(['model', 'res_id', 'author_id', 'create_uid', 'parent_id', 'message_type', 'partner_ids', 'partner_cc_ids'])
    else:
        self.flush_model(['model', 'res_id', 'author_id', 'create_uid', 'parent_id', 'message_type', 'partner_ids', 'partner_cc_ids'])
    self.env['mail.notification'].flush_model(['mail_message_id', 'res_partner_id'])
    pid = self.env.user.partner_id.id

    # Non internal users see only non-private messages
    table = query.table
    if query.limit is None:
        query.limit = MAX_SEARCH_LIMIT
    if operation in ('read', 'write'):
        id_sql = table.id
        query.groupby = id_sql
        # notified: partner_ids or partner_cc_ids or needaction
        query.add_join('LEFT JOIN', 'partner_rel', 'mail_message_res_partner_rel',
            SQL('partner_rel.mail_message_id = %s AND partner_rel.res_partner_id = %s', id_sql, pid))
        query.add_join('LEFT JOIN', 'partner_cc_rel', 'mail_message_res_partner_cc_rel',
            SQL('partner_cc_rel.mail_message_id = %s AND partner_cc_rel.res_partner_id = %s', id_sql, pid))
        query.add_join('LEFT JOIN', 'needaction_rel', 'mail_notification',
            SQL('needaction_rel.mail_message_id = %s AND needaction_rel.res_partner_id = %s', id_sql, pid))
        sql = query.select(*(
            table[fname]
            for fname in ('id', 'model', 'res_id', 'author_id', 'parent_id', 'message_type', 'create_uid')
        ), SQL('bool_or(partner_rel.res_partner_id IS NOT NULL OR partner_cc_rel.res_partner_id IS NOT NULL '
               'OR needaction_rel.res_partner_id IS NOT NULL) AS notified'))
    elif operation in ('create', 'unlink'):
        sql = query.select(*(
            table[fname]
            for fname in ('id', 'model', 'res_id', 'author_id', 'parent_id', 'message_type')
        ))
    else:
        raise ValueError(_('Wrong operation name (%s)', operation))
    # skip flush which is already done
    self.env.cr.execute(sql)
    messages_to_check = {
        values['id']: values
        for values in self.env.cr.dictfetchall()
    }
    if len(messages_to_check) == MAX_SEARCH_LIMIT:  # avoid out of memory
        raise UserError(self.env._(
            "Too many messages to be processed.\n"
            "Please apply additional filters to reduce the number of potential messages."
        ))
    accessible = self.browse(messages_to_check)
    if not messages_to_check:
        return accessible

    # Author condition (READ, WRITE, CREATE (private))
    if operation == 'read':
        uid = self.env.uid
        messages_to_check = {
            mid: message
            for mid, message in messages_to_check.items()
            if message['author_id'] != pid
            and message['create_uid'] != uid
        }
    elif operation == 'write':
        messages_to_check = {
            mid: message
            for mid, message in messages_to_check.items()
            if message['author_id'] != pid
        }
    elif operation == 'create':
        messages_to_check = {
            mid: message
            for mid, message in messages_to_check.items()
            if message['model'] and message['res_id']
            if message['message_type'] != 'user_notification'
        }

    if not messages_to_check:
        return accessible

    # Recipients condition, for read and write (partner_ids)
    # keep on top, useful for systray notifications
    if operation in ('read', 'write'):
        messages_to_check = {
            mid: message
            for mid, message in messages_to_check.items()
            if not message['notified']
        }
        if not messages_to_check:
            return accessible

    # CRUD: Access rights related to the document
    # {document_model_name: {document_id: message_ids}}
    model_docid_msgids = defaultdict(lambda: defaultdict(list))
    for mid, message in messages_to_check.items():
        if (
            (model := message['model'])
            and (res_id := message['res_id'])
            and message['message_type'] != 'user_notification'
        ):
            model_docid_msgids[model][res_id].append(mid)

    for mid in _find_allowed_doc_ids(self.env, model_docid_msgids, operation):
        messages_to_check.pop(mid)

    if not messages_to_check:
        return accessible

    # Parent condition, for create (check for received notifications for the created message parent)
    if operation == 'create':
        parent_ids_msg_ids = defaultdict(list)
        for mid, message in messages_to_check.items():
            if message.get('parent_id'):
                parent_ids_msg_ids[message['parent_id']].append(mid)
        if parent_ids_msg_ids:
            query = SQL(
                """ SELECT mail_message_id
                      FROM mail_message_res_partner_rel
                     WHERE res_partner_id = %s
                       AND mail_message_id = ANY (%s)
                     UNION
                    SELECT mail_message_id
                      FROM mail_message_res_partner_cc_rel
                     WHERE res_partner_id = %s
                       AND mail_message_id = ANY (%s) """,
                pid, list(parent_ids_msg_ids), pid, list(parent_ids_msg_ids),
            )
            for [parent_id] in self.env.execute_query(query):
                for mid in parent_ids_msg_ids[parent_id]:
                    messages_to_check.pop(mid)

        if not messages_to_check:
            return accessible

    return accessible - self.browse(messages_to_check)

def _make_access_error_message(self, operation, domain):
    if not domain.is_false():
        return AccessError(self.env._(
            "The requested operation cannot be completed due to security restrictions. "
            "Please contact your system administrator.\n\n"
            "(Document type: %(type)s, Operation: %(operation)s)\n\n"
            "Records: %(records)s, User: %(user)s",
            type=self._description,
            operation=operation,
            records=self.ids[:6],
            user=self.env.uid,
        ))
    return super()._make_access_error_message(operation, domain)

def _get_with_access(self, mode="read", **kwargs):
    if not self:
        return self
    self.ensure_one()
    if self.env.user._is_admin():
        return self
    # sanity check on kwargs
    allowed_params = self.env[self.sudo().model or 'mail.thread']._get_allowed_access_params()
    if invalid := (set((kwargs or {}).keys()) - allowed_params):
        _logger.warning("Invalid parameters to _get_with_access: %s", invalid)
    if self.sudo(False).has_access(mode):
        return self
    if self.model and self.res_id:
        thread_su = self.env[self.model].browse(self.res_id).sudo()
        for domain, access_mode in thread_su._mail_get_operation_for_mail_message_operation(mode):
            if thread_su.filtered_domain(domain):
                if self.env[self.model]._get_thread_with_access(self.res_id, mode=access_mode, **kwargs):
                    return self
                break
    return self.browse()

def create(self, vals_list):
    for values in vals_list:
        if not (self.env.su or self.env.user.has_group('base.group_user')):
            values.pop('author_id', None)
            values.pop('email_from', None)
            self = self.with_context({k: v for k, v in self.env.context.items() if k not in ['default_author_id', 'default_email_from']})  # noqa: PLW0642
        if 'email_from' not in values:  # needed to compute reply_to
            _author_id, email_from = self.env['mail.thread']._message_compute_author(values.get('author_id'), email_from=None)
            values['email_from'] = email_from
        if not values.get('message_id'):
            values['message_id'] = self._get_message_id(values)
        if 'reply_to' not in values:
            values['reply_to'] = self._get_reply_to(values)

        if not values.get('attachment_ids', True):
            # pop empty values
            del values['attachment_ids']
        # extract base64 images
        if 'body' in values:
            Attachments = self.env['ir.attachment'].with_context(clean_context(self.env.context))
            data_to_url = {}
            def base64_to_boundary(match):
                key = match.group(2)
                if not data_to_url.get(key):
                    name = match.group(4) if match.group(4) else 'image%s' % len(data_to_url)
                    try:
                        attachment = Attachments.create({
                            'name': name,
                            'raw': match.group(2),
                            'res_model': values.get('model'),
                            'res_id': values.get('res_id'),
                        })
                    except binascii_error:
                        _logger.warning("Impossible to create an attachment out of badly formated base64 embedded image. Image has been removed.")
                        return match.group(3)  # group(3) is the url ending single/double quote matched by the regexp
                    else:
                        attachment.generate_access_token()
                        attachments = values.setdefault('attachment_ids', [])
                        attachments.append((4, attachment.id))
                        data_to_url[key] = ['/web/image/%s?access_token=%s' % (attachment.id, attachment.access_token), name, attachment.id]
                # data-attachment-id helps identify image attachments that are already inserted in the body
                # this is notably used to avoid displaying them twice in the chatter
                return f'{data_to_url[key][0]}{match.group(3)} alt="{data_to_url[key][1]}" data-attachment-id="{data_to_url[key][2]}"'
            values['body'] = _image_dataurl.sub(base64_to_boundary, values['body'] or '')

    messages = super().create(vals_list)

    # link back attachments to records, to filter out attachments linked to
    # the same records as the message (considered as ok if message is ok)
    # and check rights on other documents
    attachments_tocheck = self.env['ir.attachment']
    doc_to_attachment_ids = defaultdict(set)
    if all(isinstance(command, int) or command[0] in (4, 6)
           for values in vals_list
           for command in values.get('attachment_ids', ())):
        for values in vals_list:
            message_attachment_ids = set()
            for command in values.get('attachment_ids', ()):
                if isinstance(command, int):
                    message_attachment_ids.add(command)
                elif command[0] == 6:
                    message_attachment_ids |= set(command[2])
                else:  # command[0] == 4:
                    message_attachment_ids.add(command[1])
            if message_attachment_ids:
                key = (values.get('model'), values.get('res_id'))
                doc_to_attachment_ids[key] |= message_attachment_ids

        attachment_ids_all = {
            attachment_id
            for doc_attachment_ids in doc_to_attachment_ids
            for attachment_id in doc_attachment_ids
        }
        AttachmentSudo = self.env['ir.attachment'].sudo().with_prefetch(list(attachment_ids_all))
        for (model, res_id), doc_attachment_ids in doc_to_attachment_ids.items():
            # check only attachments belonging to another model, access already
            # checked on message for other attachments
            attachments_tocheck += AttachmentSudo.browse(doc_attachment_ids).filtered(
                lambda att: att.res_model != model or att.res_id != res_id
            ).sudo(False)
    else:
        attachments_tocheck = messages.attachment_ids  # fallback on read if any unknown command
    if attachments_tocheck:
        attachments_tocheck.check_access('read')

    messages.filtered(lambda msg: msg._is_thread_message() and msg.message_type != 'user_notification')._invalidate_documents()

    return messages

def write(self, vals):
    if not (self.env.su or self.env.user.has_group('base.group_user')):
        vals.pop('author_id', None)
        vals.pop('email_from', None)
    record_changed = 'model' in vals or 'res_id' in vals
    if record_changed and not self.env.is_system():
        raise AccessError(_("Only administrators can modify 'model' and 'res_id' fields."))
    if record_changed or 'message_type' in vals:
        self._invalidate_documents()
    res = super().write(vals)
    if vals.get('attachment_ids'):
        self.attachment_ids.check_access('read')
    if 'notification_ids' in vals or record_changed:
        self._invalidate_documents()
    return res

def unlink(self):
    # cascade-delete attachments that are directly attached to the message (should only happen
    # for mail.messages that act as parent for a standalone mail.mail record).
    # the cache of the related document doesn't need to be invalidate (see @_invalidate_documents)
    # because the unlink method invalidates the whole cache anyway
    if not self:
        return True
    self.check_access('unlink')
    self.mapped('attachment_ids').filtered(
        lambda attach: attach.res_model == self._name and (attach.res_id in self.ids or attach.res_id == 0)
    ).unlink()
    messages_by_partner = defaultdict(lambda: self.env['mail.message'])
    partners_with_user = (self.partner_ids | self.partner_cc_ids).filtered('user_ids')
    for elem in self:
        for partner in (
            (elem.partner_ids | elem.partner_cc_ids) & partners_with_user | elem.notification_ids.author_id
        ):
            messages_by_partner[partner] |= elem
    # Notify front-end of messages deletion for partners having a user
    for partner, messages in messages_by_partner.items():
        partner._bus_send("mail.message/delete", {"message_ids": messages.ids})
    return super().unlink()

